var t=`0243-kleftiko`;var n=`world-0243`;var o=`GR`;var a=`southern-europe`;var r=4;var s=267;var l={en:`Kleftiko`,ua:`Клефтіко`};var d={en:`A traditional Greece dish made with lamb shoulder, lemon juice, garlic, potato. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: лопатка ягняти, лимонний сік, часник, картопля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 120 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 120 хвилин.`,t:[`marinating`],m:120,i:[[`lamb-shoulder`,950,`g`],[`lemon-juice`,60,`ml`],[`extra-virgin-olive-oil`,65,`ml`],[`garlic`,5,`clove`],[`dried-oregano`,6,`g`],[`table-salt`,null,`to_taste`]]},{en:`Roast in a preheated 190°C oven for about 145 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 145 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:145,i:[[`potato`,650,`g`],[`water`,250,`ml`],[`bay-leaf`,2,`leaf`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`lemon`,1,`pcs`]]}];var g={slug:t,id:n,country:`GR`,region:a,servings:4,minutes:267,title:l,text:d,steps:u};export{o as country,g as default,n as id,s as minutes,a as region,r as servings,t as slug,u as steps,d as text,l as title};